using System;using System.IO;using System.Linq;using System.Collections.Generic;using MashBoxSDK.AnimationStudio;using UnityEditor;using UnityEngine;using Object=UnityEngine.Object;
public static class StudioBevelLimitsValidation
{
 public static void Run(){Mesh m=null;try{int sides=8;var v=new List<Vector3>();for(int i=0;i<sides;i++){float a=i*Mathf.PI*2/sides;v.Add(new Vector3(Mathf.Cos(a),0,Mathf.Sin(a)));}v.Add(new Vector3(0,1.5f,0));var faces=new List<int[]>{Enumerable.Range(0,sides).ToArray()};for(int i=0;i<sides;i++)faces.Add(new[]{(i+1)%sides,i,sides});var triangles=new List<int>();var metadata=new List<int>();foreach(var f in faces){metadata.Add(0);metadata.Add(f.Length);metadata.AddRange(f);for(int i=1;i<f.Length-1;i++)triangles.AddRange(new[]{f[0],f[i],f[i+1]});}m=new Mesh();m.SetVertices(v);m.SetTriangles(triangles,0);m.RecalculateNormals();m.RecalculateBounds();var node=new StudioModelDocument.Node{mesh=m,cutPolygons=metadata.ToArray(),cutTriangles=m.triangles};var edges=new HashSet<(int,int)>();foreach(var f in faces)for(int i=0;i<f.Length;i++){int a=f[i],b=f[(i+1)%f.Length];edges.Add(a<b?(a,b):(b,a));}var topology=new StudioMeshCuts(node);topology.BevelEdges(node,edges,new StudioMeshCuts.BevelOptions{Width=.2f,Subdivisions=32,Tension=1,Junction=StudioMeshCuts.BevelJunction.Uniform});var points=m.vertices;var indices=m.triangles;var ids=new Dictionary<Vector3,int>();var uses=new Dictionary<(int,int),(int count,int a,int b)>();for(int i=0;i<indices.Length;i+=3){if(Vector3.Cross(points[indices[i+1]]-points[indices[i]],points[indices[i+2]]-points[indices[i]]).sqrMagnitude==0)throw new Exception("Zero-area maximum-subdivision triangle");for(int j=0;j<3;j++){var a=points[indices[i+j]];var b=points[indices[i+(j+1)%3]];if(!ids.ContainsKey(a))ids.Add(a,ids.Count);if(!ids.ContainsKey(b))ids.Add(b,ids.Count);int x=ids[a],y=ids[b];var k=x<y?(x,y):(y,x);if(uses.TryGetValue(k,out var u)){if(u.count!=1||u.a!=y)throw new Exception("Nonmanifold maximum-subdivision edge");uses[k]=(2,u.a,u.b);}else uses.Add(k,(1,x,y));}}if(uses.Values.Any(u=>u.count!=2))throw new Exception("High-valence corner left a hole");if(ids.Count-uses.Count+indices.Length/3!=2)throw new Exception("High-valence topology changed");File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath, "../bevel-limits-result.txt")),"PASS 32 internal subdivisions on an eight-valence corner: "+m.vertexCount+" vertices, "+indices.Length/3+" triangles; closed oriented manifold with Euler characteristic 2.");}catch(Exception e){File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath, "../bevel-limits-result.txt")),e.ToString());}finally{if(m)Object.DestroyImmediate(m);EditorApplication.Exit(0);}}
}
